using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool implementations ---
var notepad = new Notepad();

// --- Build the agent ---
var agent = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .BuildAIAgent(
        instructions: """
            You are a research assistant. When given a topic:
            1. Search the web for relevant information using the search tool.
            2. Take notes on key findings using the note-taking tool.
            3. After gathering enough information, produce a concise summary
               that synthesizes your notes.
            Always cite your sources. Be thorough but concise.
            """,
        name: "ResearchAgent",
        description: "An agent that researches topics by searching the web and taking notes.",
        tools:
        [
            AIFunctionFactory.Create(SearchWebAsync),
            AIFunctionFactory.Create(notepad.SaveNote),
            AIFunctionFactory.Create(notepad.GetNotes),
        ]);

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (MAF + MEAI)       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions { Temperature = 0f, MaxOutputTokens = 4096 });

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine("═══════════════════ Results ═══════════════════\n");
Console.WriteLine(response.Text);

if (notepad.NoteCount > 0)
{
    Console.WriteLine($"\n📝 {notepad.NoteCount} note(s) were taken during research.");
}

// --- Tool functions ---

[Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
static async Task<string> SearchWebAsync(
    [Description("The search query to look up")] string query)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (compatible; educational project)");

    try
    {
        // Use DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var ddg = await http.GetFromJsonAsync<JsonElement>(url);

        var results = new List<string>();

        // Abstract (main answer)
        var abstractText = ddg.GetProperty("Abstract").GetString();
        var abstractSource = ddg.GetProperty("AbstractSource").GetString();
        var abstractUrl = ddg.GetProperty("AbstractURL").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            results.Add($"[Source: {abstractSource}] {abstractText}\nURL: {abstractUrl}");
        }

        // Related topics
        if (ddg.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(5))
            {
                var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                {
                    results.Add($"{text}\nURL: {link}");
                }
            }
        }

        return results.Count > 0
            ? string.Join("\n---\n", results)
            : $"No results found for \"{query}\". Try rephrasing or breaking the query into smaller parts.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("No topic provided.")
        : input;
}

// --- Notepad tool class ---

sealed class Notepad
{
    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Save a research note. Use this to record key findings, facts, or quotes discovered during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        var numbered = _notes.Select((n, i) => $"[{i + 1}] {n}");
        return string.Join("\n", numbered);
    }
}

